defense.secure_config:
# Remove unconstrained delegation:
Get-ADComputer -Filter {TrustedForDelegation -eq $true} | Where-Object {$_.Name -notlike '*DC*'} | ForEach-Object {
  Set-ADAccountControl $_ -TrustedForDelegation $false
  Set-ADComputer $_ -TrustedToAuthForDelegation $false
  Write-Output "Fixed: $($_.Name)"
}

# Disable Print Spooler on all DCs:
Get-ADDomainController -Filter * | ForEach-Object {
  Invoke-Command -ComputerName $_.Name -ScriptBlock { Stop-Service Spooler -Force; Set-Service Spooler -StartupType Disabled }
}

# Protected Users — blocks TGT forwarding:
Get-ADGroupMember 'Domain Admins' | ForEach-Object { Add-ADGroupMember 'Protected Users' $_ }

# SIEM: alert on DC-to-non-DC SMB connection:
# Sysmon Event 3: SourceImage=SYSTEM DestinationPort=445 SourceHost=DC* DestinationHost!=DC* → ALERT
